import os
import re
from typing import List, Optional, Tuple, Dict

from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

INPUT_PATH = "/root/data/workbook.xlsx"
OUTPUT_PATH = "/root/output/result.xlsx"


def cell_str(v):
    if v is None:
        return ""
    return str(v)


def normalize_text(v) -> str:
    return re.sub(r"\s+", " ", cell_str(v)).strip().lower()


def print_range(ws, title: str, min_row: int, max_row: int, min_col: int, max_col: int):
    print(f"\n--- {ws.title}: {title} ({get_column_letter(min_col)}{min_row}:{get_column_letter(max_col)}{max_row}) ---")
    for r in range(min_row, max_row + 1):
        parts = []
        for c in range(min_col, max_col + 1):
            v = ws.cell(r, c).value
            parts.append(f"{get_column_letter(c)}{r}={v!r}")
        print("  " + ", ".join(parts))


def print_col(ws, title: str, col_letter: str, start_row: int, end_row: int):
    print(f"\n--- {ws.title}: {title} ({col_letter}{start_row}:{col_letter}{end_row}) ---")
    col = ws[col_letter]
    for r in range(start_row, end_row + 1):
        v = col[r - 1].value
        print(f"  {col_letter}{r}={v!r}")


def get_task_years(task_ws) -> List:
    years = []
    for c in range(8, 13):  # H..L
        years.append(task_ws.cell(10, c).value)
    return years


def find_best_year_header_row(data_ws, task_years: List, search_rows: int = 40) -> Tuple[int, List[int]]:
    """Return (header_row, year_col_indices) where year_col_indices are columns matching task_years."""
    # Try to match numeric years (possibly as int/float/str).
    wanted = [cell_str(y).strip() for y in task_years]

    def is_match(cell_val, wanted_str):
        if cell_val is None:
            return False
        s = cell_str(cell_val).strip()
        # normalize 2020.0 -> 2020
        if re.fullmatch(r"\d+\.0", s):
            s = s[:-2]
        return s == wanted_str

    best_row = None
    best_cols = []
    best_score = -1

    max_col = data_ws.max_column
    for r in range(1, min(search_rows, data_ws.max_row) + 1):
        # Find columns for each wanted year.
        cols_for_year = {}
        for c in range(1, max_col + 1):
            v = data_ws.cell(r, c).value
            if v is None:
                continue
            s = cell_str(v).strip()
            if re.fullmatch(r"\d+\.0", s):
                s = s[:-2]
            if s in wanted:
                cols_for_year[s] = c
        score = len(cols_for_year)
        if score > best_score:
            best_score = score
            best_row = r
            # Keep columns in task order.
            best_cols = [cols_for_year.get(w) for w in wanted]

    if best_row is None or best_score < max(3, len(task_years) - 2):
        raise RuntimeError(
            f"Could not confidently locate a year header row in Data sheet. Best match row={best_row}, score={best_score}."
        )

    if any(c is None for c in best_cols):
        missing = [task_years[i] for i, c in enumerate(best_cols) if c is None]
        raise RuntimeError(f"Found year header row {best_row} but missing columns for years: {missing}")

    return best_row, best_cols


def find_series_code_rows(data_ws, code_col: int, candidate_codes: List[str], search_start_row: int = 1) -> Tuple[int, int]:
    """Find min/max rows in Data sheet where series codes appear in code_col."""
    wanted = {c for c in candidate_codes if c}
    found_rows = []
    for r in range(search_start_row, data_ws.max_row + 1):
        v = data_ws.cell(r, code_col).value
        if v is None:
            continue
        s = cell_str(v).strip()
        if s in wanted:
            found_rows.append(r)
    if not found_rows:
        raise RuntimeError("Could not find any Task series codes in Data sheet column A.")
    return min(found_rows), max(found_rows)


def detect_block_roles(task_ws) -> Dict[str, int]:
    """Try to detect which block start row corresponds to success/failed/capacity."""
    blocks = [12, 19, 26]
    role_keywords = {
        "success": ["successful", "success", "ok", "passed"],
        "failed": ["failed", "failure", "errors", "error"],
        "capacity": ["compute capacity", "capacity", "compute"],
    }

    def score_block(start_row: int) -> Dict[str, int]:
        # Look around the block title row and within left label area.
        text_cells = []
        for r in range(start_row - 2, start_row + 1):
            if r < 1:
                continue
            for c in range(1, 8):  # A..G left side
                v = task_ws.cell(r, c).value
                if v is not None:
                    text_cells.append(normalize_text(v))
        blob = " | ".join([t for t in text_cells if t])
        scores = {role: 0 for role in role_keywords}
        for role, kws in role_keywords.items():
            for kw in kws:
                if kw in blob:
                    scores[role] += 1
        return scores

    # Choose best matching block per role.
    best_for_role = {"success": (None, -1), "failed": (None, -1), "capacity": (None, -1)}
    for b in blocks:
        scores = score_block(b)
        for role in best_for_role:
            if scores[role] > best_for_role[role][1]:
                best_for_role[role] = (b, scores[role])

    # If detection is weak/ambiguous, fallback to default mapping.
    detected = {role: best_for_role[role][0] for role in best_for_role}
    strengths = {role: best_for_role[role][1] for role in best_for_role}

    # ensure unique mapping; otherwise fallback
    if len(set(detected.values())) < 3 or any(strengths[r] == 0 for r in strengths):
        return {"success": 12, "failed": 19, "capacity": 26, "note": "fallback_default"}

    detected["note"] = "keyword_detected"
    return detected


def detect_stats_row_mapping(task_ws) -> Dict[int, str]:
    """Map task rows 42-47 to stat types based on labels in column G or D."""
    rows = list(range(42, 48))
    mapping = {}

    def classify(label: str) -> Optional[str]:
        t = normalize_text(label)
        if not t:
            return None
        if "min" in t:
            return "min"
        if "max" in t:
            return "max"
        if "median" in t:
            return "median"
        if "mean" in t or "average" in t or t == "avg":
            return "average"
        if "25" in t or "0.25" in t or "p25" in t or "q1" in t or "quartile" in t and "1" in t:
            return "p25"
        if "75" in t or "0.75" in t or "p75" in t or "q3" in t:
            return "p75"
        return None

    for r in rows:
        label = task_ws.cell(r, 7).value  # G
        if label is None or normalize_text(label) == "":
            label = task_ws.cell(r, 4).value  # D fallback
        stat = classify(label)
        if stat:
            mapping[r] = stat

    # If we couldn't classify all, fill with default order.
    default_order = {42: "min", 43: "max", 44: "median", 45: "average", 46: "p25", 47: "p75"}
    for r in rows:
        if r not in mapping:
            mapping[r] = default_order[r]

    return mapping


def main():
    wb = load_workbook(INPUT_PATH, keep_vba=False, data_only=False)

    print("=== Preliminary inspection ===")
    print("Sheet names:", wb.sheetnames)

    if "Task" not in wb.sheetnames or "Data" not in wb.sheetnames:
        raise RuntimeError("Workbook must contain 'Task' and 'Data' sheets")

    task_ws = wb["Task"]
    data_ws = wb["Data"]

    # Task sheet inspections requested
    print_col(task_ws, "Series codes block 1", "D", 12, 17)
    print_col(task_ws, "Series codes block 2", "D", 19, 24)
    print_col(task_ws, "Series codes block 3", "D", 26, 31)

    print_range(task_ws, "Years row", 10, 10, 8, 12)  # H-L

    print_range(task_ws, "H35:L40", 35, 40, 8, 12)
    print_range(task_ws, "H42:L47", 42, 47, 8, 12)
    print_range(task_ws, "H50:L50", 50, 50, 8, 12)

    # labels in column D/G for rows 35-50
    print_range(task_ws, "Labels D/G rows 35-50", 35, 50, 4, 7)

    # Data sheet inspections requested
    # Row 1 headers (first ~20 cols to keep output readable)
    print_range(data_ws, "Row 1 (first 20 cols)", 1, 1, 1, min(20, data_ws.max_column))

    print_col(data_ws, "Series codes column A sample (rows 21-38)", "A", 21, 38)

    print_range(data_ws, "Row 20 first 20 cols", 20, 20, 1, min(20, data_ws.max_column))
    print_range(data_ws, "Row 21 first 20 cols", 21, 21, 1, min(20, data_ws.max_column))

    # Determine layout
    task_years = get_task_years(task_ws)
    print("\nTask years (Task!H10:L10):", task_years)

    header_row, year_cols = find_best_year_header_row(data_ws, task_years, search_rows=50)
    year_col_letters = [get_column_letter(c) for c in year_cols]
    print(f"\nDetected Data year header row: {header_row}")
    print("Detected year columns (matching Task years order):", list(zip(task_years, year_col_letters)))

    # Determine series codes from Task blocks
    task_codes = []
    for r in list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32)):
        v = task_ws.cell(r, 4).value  # D
        if v is not None and str(v).strip() != "":
            task_codes.append(str(v).strip())
    task_codes = sorted(set(task_codes))

    code_col = 1  # assume Data series codes in column A; validate by presence.
    start_row, end_row = find_series_code_rows(data_ws, code_col, task_codes, search_start_row=1)
    print(f"\nDetected series-code rows in Data sheet: {start_row}:{end_row} (column A)")

    first_year_col = min(year_cols)
    last_year_col = max(year_cols)
    first_year_letter = get_column_letter(first_year_col)
    last_year_letter = get_column_letter(last_year_col)

    print("\nLookup orientation confirmation:")
    print(f"- Series codes in Data!{get_column_letter(code_col)}{start_row}:{get_column_letter(code_col)}{end_row}")
    print(f"- Years in Data!{first_year_letter}{header_row}:{last_year_letter}{header_row}")
    print(f"- Values in Data!{first_year_letter}{start_row}:{last_year_letter}{end_row}")

    # Build formula template
    index_range = f"Data!${first_year_letter}${start_row}:${last_year_letter}${end_row}"
    match_codes_range = f"Data!$A${start_row}:$A${end_row}"
    match_years_range = f"Data!${first_year_letter}${header_row}:${last_year_letter}${header_row}"

    def make_lookup_formula(task_row: int, task_col: int) -> str:
        col_letter = get_column_letter(task_col)
        return (
            f"=INDEX({index_range}, "
            f"MATCH($D{task_row}, {match_codes_range}, 0), "
            f"MATCH({col_letter}$10, {match_years_range}, 0))"
        )

    print("\n=== Step 1: Writing INDEX/MATCH formulas into H12:L17, H19:L24, H26:L31 ===")
    blocks = [(12, 17), (19, 24), (26, 31)]
    for (r0, r1) in blocks:
        for r in range(r0, r1 + 1):
            for c in range(8, 13):  # H..L
                task_ws.cell(r, c).value = make_lookup_formula(r, c)

    # Determine which block is which metric
    roles = detect_block_roles(task_ws)
    print("\n=== Step 2: Determine metric blocks ===")
    print("Block role detection:", roles)
    success_start = roles.get("success", 12)
    failed_start = roles.get("failed", 19)
    capacity_start = roles.get("capacity", 26)

    print(f"Using block starts: success={success_start}, failed={failed_start}, capacity={capacity_start}")

    # Net reliability gap in H35:L40
    print("\n=== Step 2: Writing Net reliability gap formulas into H35:L40 ===")
    for i in range(6):
        out_row = 35 + i
        s_row = success_start + i
        f_row = failed_start + i
        c_row = capacity_start + i
        for c in range(8, 13):
            col_letter = get_column_letter(c)
            task_ws.cell(out_row, c).value = f"=({col_letter}{s_row}-{col_letter}{f_row})/{col_letter}{c_row}*100"

    # Summary stats in H42:L47
    stats_map = detect_stats_row_mapping(task_ws)
    print("\n=== Step 2: Writing summary stats formulas into H42:L47 ===")
    print("Detected/assigned stats mapping:", stats_map)

    def stat_formula(stat: str, col_letter: str) -> str:
        rng = f"{col_letter}35:{col_letter}40"
        if stat == "min":
            return f"=MIN({rng})"
        if stat == "max":
            return f"=MAX({rng})"
        if stat == "median":
            return f"=MEDIAN({rng})"
        if stat == "average":
            return f"=AVERAGE({rng})"
        if stat == "p25":
            return f"=PERCENTILE({rng},0.25)"
        if stat == "p75":
            return f"=PERCENTILE({rng},0.75)"
        raise ValueError(f"Unknown stat: {stat}")

    for r in range(42, 48):
        stat = stats_map[r]
        for c in range(8, 13):
            col_letter = get_column_letter(c)
            task_ws.cell(r, c).value = stat_formula(stat, col_letter)

    # Weighted mean in H50:L50
    print("\n=== Step 3: Writing weighted mean formulas into H50:L50 ===")
    w0 = capacity_start
    w1 = capacity_start + 5
    for c in range(8, 13):
        col_letter = get_column_letter(c)
        values_rng = f"{col_letter}35:{col_letter}40"
        weights_rng = f"{col_letter}{w0}:{col_letter}{w1}"
        task_ws.cell(50, c).value = f"=SUMPRODUCT({values_rng}, {weights_rng}) / SUM({weights_rng})"

    # Save
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)
    wb.save(OUTPUT_PATH)
    print(f"\nSaved workbook to {OUTPUT_PATH}")

    # Validation
    wb2 = load_workbook(OUTPUT_PATH, keep_vba=False, data_only=False)
    print("\n=== Validation after saving ===")
    print("Sheet names (reloaded):", wb2.sheetnames)
    if wb2.sheetnames != wb.sheetnames:
        print("WARNING: sheetnames differ from original!")

    t2 = wb2["Task"]
    sample_cells = [
        "H12", "L17", "H19", "L24", "H26", "L31",
        "H35", "H40", "H42", "H47", "H50", "L50",
    ]
    for addr in sample_cells:
        v = t2[addr].value
        print(f"Task!{addr} => {v!r} (is_formula={isinstance(v, str) and v.startswith('=')})")

    exists = os.path.exists(OUTPUT_PATH)
    print(f"\nFile exists at {OUTPUT_PATH}: {exists}")


if __name__ == "__main__":
    main()

